/**
 * Inyectado por electron-vite (ver electron.vite.config.ts, `define`) desde
 * el "version" de package.json en tiempo de build. Unica fuente de verdad
 * para el numero de version mostrado en la app — nunca hardcodear el string
 * de version en otro lugar del codigo.
 */
declare const __APP_VERSION__: string
